// 1. Get raw Gemini text output
const rawText = $input.first().json.content.parts[0].text;

// 2. Clean markdown fences
let cleaned = rawText
  .replace(/```json\s*/gi, '')
  .replace(/```\s*/g, '')
  .trim();

// 3. Extract JSON object
const firstBrace = cleaned.indexOf('{');
const lastBrace = cleaned.lastIndexOf('}');
if (firstBrace === -1 || lastBrace === -1 || lastBrace <= firstBrace) {
  throw new Error('No JSON object found in Gemini response');
}
cleaned = cleaned.substring(firstBrace, lastBrace + 1);

// 4. Fix common LLM JSON issues
cleaned = cleaned.replace(/,\s*([}\]])/g, '$1');
cleaned = cleaned.replace(/[\x00-\x08\x0B\x0C\x0E-\x1F]/g, '');

// 5. Parse
let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  // Fix unescaped newlines
  cleaned = cleaned.replace(/([^\\])\n/g, '$1\\n');
  cleaned = cleaned.replace(/([^\\])\r/g, '$1\\r');
  try {
    parsed = JSON.parse(cleaned);
  } catch (err2) {
    throw new Error('Invalid JSON: ' + err2.message);
  }
}

// 6. Validate required keys
const requiredKeys = ['transcriptSegments', 'dailyLog', 'tasks', 'audit'];
for (const key of requiredKeys) {
  if (!(key in parsed)) {
    parsed[key] = key === 'tasks' ? [] : key === 'transcriptSegments' ? [] : {};
  }
}

// 7. Ensure transcript segments have speaker field
if (Array.isArray(parsed.transcriptSegments)) {
  parsed.transcriptSegments = parsed.transcriptSegments.map(seg => ({
    ...seg,
    speaker: seg.speaker || seg.speakerName || 'Unknown Speaker',
    diarizationConfidence: seg.diarizationConfidence || 0
  }));
}

// 8. Ensure dailyLog summaryBullets are objects
if (parsed.dailyLog && Array.isArray(parsed.dailyLog.summaryBullets)) {
  parsed.dailyLog.summaryBullets = parsed.dailyLog.summaryBullets.map((b, i) => {
    if (typeof b === 'string') {
      return {
        bulletId: `bullet_${i}`,
        text: b,
        category: 'work_performed',
        source_transcript_segment_ids: []
      };
    }
    return b;
  });
}

// 9. Ensure qualityScoring exists
if (!parsed.qualityScoring) {
  parsed.qualityScoring = {
    transcriptConfidence: parsed.quality?.transcriptionConfidence || 0,
    diarizationConfidence: parsed.quality?.speakerRecognitionConfidence || 0
  };
}

return { json: parsed };
